const fs = require("node:fs");
const path = require("node:path");
const { createHash } = require("node:crypto");
const { execFileSync, spawn } = require("node:child_process");

async function main() {
  const arch = { arm64: "aarch64", x64: "x86_64" }[process.arch];
  if (process.platform !== "darwin" || !arch) {
    throw new Error("This test supports Apple Silicon and Intel macOS.");
  }

  const version = "0.11.15";
  const platform = `${arch}-apple-darwin`;
  const asset = `uv-${platform}.tar.gz`;
  const url = `https://github.com/astral-sh/uv/releases/download/${version}/${asset}`;
  const root = path.join(require("node:os").homedir(), ".personal-health-memory", "runtime");
  const destination = path.join(root, `${version}-${platform}`);
  const uvx = path.join(destination, "uvx");

  if (!fs.existsSync(uvx)) {
    fs.mkdirSync(root, { recursive: true, mode: 0o700 });
    const staging = fs.mkdtempSync(path.join(root, "download-"));
    try {
      const archive = path.join(staging, asset);
      const checksum = path.join(staging, "checksum");
      for (const [from, to] of [[url, archive], [`${url}.sha256`, checksum]]) {
        execFileSync("/usr/bin/curl", [
          "--fail", "--silent", "--show-error", "--location",
          "--max-time", "60", "--output", to, from,
        ]);
      }
      const expected = fs.readFileSync(checksum, "utf8").trim().split(/\s+/)[0];
      const actual = createHash("sha256").update(fs.readFileSync(archive)).digest("hex");
      if (!/^[a-f0-9]{64}$/i.test(expected) || actual !== expected.toLowerCase()) {
        throw new Error("uv archive checksum mismatch.");
      }

      execFileSync("/usr/bin/tar", ["-xzf", archive, "-C", staging]);
      const extracted = path.join(staging, `uv-${platform}`);
      fs.accessSync(path.join(extracted, "uvx"), fs.constants.X_OK);
      try {
        fs.renameSync(extracted, destination);
      } catch (error) {
        if (!["EEXIST", "ENOTEMPTY"].includes(error.code)) throw error;
        fs.accessSync(uvx, fs.constants.X_OK);
      }
      console.error("[health-memory-bootstrap-test] Verified uv archive:", actual);
    } finally {
      fs.rmSync(staging, { recursive: true, force: true });
    }
  }

  console.error("[health-memory-bootstrap-test] Launching:", uvx);
  const wheelHash = "fafa6f7eaaff90684ceadf2e112360e7de7f317ccf2bf8e7d6a92e715385f861";
  const wheelDir = path.join(root, "wheels", wheelHash);
  const wheelPath = path.join(wheelDir, "jiuwen_personal_health_memory-0.1.0-py3-none-any.whl");
  fs.mkdirSync(wheelDir, { recursive: true, mode: 0o700 });

  if (!fs.existsSync(wheelPath) ||
      createHash("sha256").update(fs.readFileSync(wheelPath)).digest("hex") !== wheelHash) {
    const payload = Buffer.from("", "base64");
    if (createHash("sha256").update(payload).digest("hex") !== wheelHash) {
      throw new Error("Bundled connector wheel checksum mismatch.");
    }
    const pendingDir = fs.mkdtempSync(path.join(wheelDir, "write-"));
    try {
      const pendingWheel = path.join(pendingDir, wheelPath.split(path.sep).pop());
      fs.writeFileSync(pendingWheel, payload, { mode: 0o600 });
      fs.renameSync(pendingWheel, wheelPath);
    } finally {
      fs.rmSync(pendingDir, { recursive: true, force: true });
    }
  }

  const launchArgs = process.argv.slice(1).map(
    (arg) => arg === "BUNDLED_CONNECTOR_WHEEL" ? wheelPath : arg
  );
  const child = spawn(uvx, launchArgs, { stdio: "inherit" });
  child.on("error", (error) => {
    console.error("[health-memory-bootstrap-test]", error.message);
    process.exitCode = 1;
  });
  child.on("exit", (code) => { process.exitCode = code ?? 1; });
  for (const signal of ["SIGINT", "SIGTERM"]) {
    process.on(signal, () => child.kill(signal));
  }
}

main().catch((error) => {
  console.error("[health-memory-bootstrap-test]", error.message);
  process.exitCode = 1;
});
